changeSet.sql:
CREATE TABLE IF NOT EXISTS integration.ableid_setting ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), base_url TEXT NOT NULL, project_id TEXT NOT NULL, secret TEXT, hook_url TEXT, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS integration.ableid_attempt ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), attempt_id TEXT NOT NULL, transaction_id TEXT NOT NULL, user_in TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', payload TEXT, created_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_modified_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX IF NOT EXISTS idx_ableid_attempt_attempt_id ON integration.ableid_attempt (attempt_id);
